import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StreamTokenizer st = new StreamTokenizer(br);

        st.nextToken();
        int n = (int) st.nval;

        int substituir = 0;
        int consertar = 0;

        for (int i = 0; i < n; i++) {
            st.nextToken();
            int x = (int) st.nval;
            if (x < 50) {
                substituir++;
            } else if (x < 85) {
                consertar++;
            }
        }

        System.out.println(substituir + " " + consertar);
    }
}
